import { test, expect } from '@playwright/test';

test.describe('Multiple Concurrent API Calls Resolution', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/data');
  });

  test('should resolve multiple concurrent API calls before displaying data', async ({ page }) => {
    // Intercept the first API call
    await page.route('**/api/data/1', (route) => {
      route.abort('failed');
    });

    // Intercept the second API call
    await page.route('**/api/data/2', (route) => {
      route.continue();
    });

    // Intercept the third API call
    await page.route('**/api/data/3', (route) => {
      route.continue();
    });

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify data container is empty
    const dataContainer = page.getByTestId('data-container');
    await expect(dataContainer).toHaveText('');

    // Wait for the first API call to fail and the others to resolve
    await page.waitForTimeout(500);

    // Verify error message for the failed call
    const errorMessage = page.getByText('Failed to load data');
    await expect(errorMessage).toBeVisible();

    // Verify data is displayed from successful calls
    const dataItems = page.getByTestId('data-item');
    await expect(dataItems).toHaveCount(2);

    // Verify data content
    const item1 = page.getByText('Data from API 2');
    const item2 = page.getByText('Data from API 3');
    await expect(item1).toBeVisible();
    await expect(item2).toBeVisible();

    // Verify loading indicator is gone
    await expect(loadingIndicator).not.toBeVisible();
  });

  test('should handle all concurrent API calls resolving successfully', async ({ page }) => {
    // Intercept all three API calls and resolve them
    await page.route('**/api/data/1', (route) => {
      route.continue();
    });

    await page.route('**/api/data/2', (route) => {
      route.continue();
    });

    await page.route('**/api/data/3', (route) => {
      route.continue();
    });

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify data container is empty initially
    const dataContainer = page.getByTestId('data-container');
    await expect(dataContainer).toHaveText('');

    // Wait for all API calls to resolve
    await page.waitForTimeout(1000);

    // Verify loading indicator is gone
    await expect(loadingIndicator).not.toBeVisible();

    // Verify all three data items are displayed
    const dataItems = page.getByTestId('data-item');
    await expect(dataItems).toHaveCount(3);

    // Verify data content
    const item1 = page.getByText('Data from API 1');
    const item2 = page.getByText('Data from API 2');
    const item3 = page.getByText('Data from API 3');
    await expect(item1).toBeVisible();
    await expect(item2).toBeVisible();
    await expect(item3).toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText('Data loaded successfully');
    await expect(successMessage).toBeVisible();
  });
});
